ed',true); end if; select * into v_c from public.mela_learning_material_content where material_id=v_m.id; return jsonb_build_object('material_key',v_m.material_key,'title',v_m.title,'summary',v_m.summary,'material_type',v_m.material_type,'access_tier',v_m.access_tier,'product_key',v_m.product_key,'subject_title',v_p.subject_title,'grade_level',v_p.grade_level,'stage_key',v_p.stage_key,'track_key',v_p.track_key,'program_title',v_p.title,'unit_title',v_u.title,'official_alignment_status',v_u.official_alignment_status,'content_markdown',v_c.content_markdown,'answer_key',v_c.answer_key,'locked',false); end $$; revoke execute on function public.get_mela_learning_material(text) from anon; grant execute on function public.get_mela_learning_material(text) to authenticated;
